# Surah Al-Furqan (chapter 25) — part 1: ayat 1-10 (IDs 2856-2865)
SURAH = 25

ENTRIES = {
2856: (
"بابرکت ہے وہ جس نے فرقان اپنے بندے پر نازل کیا تاکہ وہ جہانوں کے لیے نذیر ہو جائے",
"""۱۔ سورۂ فرقان — فرقان نازل کرنا؛ بندہ؛ نذیر؛ جہان۔
۲۔ ’’تَبَارَكَ الَّذِي نَزَّلَ الْفُرْقَانَ عَلَىٰ عَبْدِهِ لِيَكُونَ لِلْعَالَمِينَ نَذِيرًا‘‘ —بابرکت ہے وہ جس نے فرقان اپنے بندے پر نازل کیا تاکہ وہ جہانوں کے لیے نذیر ہو جائے۔
۳۔ عملی سبق: قرآن کی عظمت مانو؛ رسولؐ کی نذیربانی کو سمجھو؛ ہدایت کی تلاش کرو۔"""
),
2857: (
"وہی جس کے لیے آسمانوں اور زمین کی ملکیت ہے اور اس نے نہ بیٹا بنایا نہ اس کے لیے ملک میں کوئی شریک ہے — اور اس نے ہر چیز کو پیدا کیا پھر اسے تقدیر دے کر بنایا",
"""۱۔ اللہ — مالک؛ بیٹا نہیں؛ شریک نہیں؛ خلق؛ تقدیر۔
۲۔ ’’الَّذِي لَهُ مُلْكُ السَّمَاوَاتِ وَالْأَرْضِ وَلَمْ يَتَّخِذْ وَلَدًا وَلَمْ يَكُن لَّهُ شَرِيكٌ فِي الْمُلْكِ وَخَلَقَ كُلَّ شَيْءٍ فَقَدَّرَهُ تَقْدِيرًا‘‘ — وہی جس کے لیے آسمانوں اور زمین کی ملکیت ہے اور اس نے نہ بیٹا بنایا نہ اس کے لیے ملک میں کوئی شریک ہے — اور اس نے ہر چیز کو پیدا کیا پھر اسے تقدیر دے کر بنایا — یعنی وہی جس کے لیے آسمانوں اور زمین کی ملکیت ہے اور اس نے نہ بیٹا بنایا نہ اس کے لیے ملک میں کوئی شریک ہے اور اس نے ہر چیز کو پیدا کیا پھر اسے تقدیر دے کر بنایا۔
۳۔ عملی سبق: اللہ کو ایک مانو؛ اس کی توحید پر ایمان رکھو؛ اس کی تقدیر پر بھروسہ کرو۔"""
),
2858: (
"اور ان لوگوں نے اس کے سوا ایسے معبود بنا لیے جو کچھ پیدا نہیں کر سکتے اور وہ خود پیدا کیے جاتے ہیں — اور وہ اپنے لیے نہ کوئی نقصان رکھتے ہیں نہ نفع — اور نہ موت کے مالک ہیں نہ زندگی کے نہ دوبارہ اٹھنے کے",
"""۱۔ بتوں کی حقیقت — کچھ پیدا نہیں کرتے؛ خود مخلوق؛ بے بس؛ معبود نہیں۔
۲۔ ’’وَاتَّخَذُوا مِن دُونِهِ آلِهَۃً لَّا يَخْلُقُونَ شَيْئًا وَهُمْ يُخْلَقُونَ وَلَا يَمْلِكُونَ لِأَنفُسِهِمْ ضَرًّا وَلَا نَفْعًا وَلَا يَمْلِكُونَ مَوْتًا وَلَا حَيَاۃً وَلَا نُشُورًا‘‘ — اور ان لوگوں نے اس کے سوا ایسے معبود بنا لیے جو کچھ پیدا نہیں کر سکتے اور وہ خود پیدا کیے جاتے ہیں — اور وہ اپنے لیے نہ کوئی نقصان رکھتے ہیں نہ نفع — اور نہ موت کے مالک ہیں نہ زندگی کے نہ دوبارہ اٹھنے کے — یعنی اور ان لوگوں نے اس کے سوا ایسے معبود بنا لیے جو کچھ پیدا نہیں کر سکتے اور وہ خود پیدا کیے جاتے ہیں اور وہ اپنے لیے نہ کوئی نقصان رکھتے ہیں نہ نفع اور نہ موت کے مالک ہیں نہ زندگی کے نہ دوبارہ اٹھنے کے۔
۳۔ عملی سبق: بتوں کی عبادت چھوڑو؛ صرف اللہ کی عبادت کرو؛ اس کی قدرت پر ایمان لاؤ۔"""
),
2859: (
"اور کافروں نے کہا یہ تو فقط جھوٹ ہے جسے اس نے خود گھڑا ہے اور اس کی مدد پر دوسرے لوگوں نے کی ہے — پس انہوں نے ظلم اور جھوٹ کا ارتکاب کیا",
"""۱۔ کافروں کا الزام — فرقان جھوٹ؛ آپ کا گھڑنا؛ مدد؛ ظلم و زور۔
۲۔ ’’وَقَالَ الَّذِينَ كَفَرُوا إِنْ هَٰذَا إِلَّا إِفْكٌ افْتَرَاهُ وَأَعَانَهُ عَلَيْهِ قَوْمٌ آخَرُونَ فَقَدْ جَاءُوا ظُلْمًا وَزُورًا‘‘ — اور کافروں نے کہا یہ تو فقط جھوٹ ہے جسے اس نے خود گھڑا ہے اور اس کی مدد پر دوسرے لوگوں نے کی ہے — پس انہوں نے ظلم اور جھوٹ کا ارتکاب کیا — یعنی اور کافروں نے کہا یہ تو فقط جھوٹ ہے جسے اس نے خود گھڑا ہے اور اس کی مدد پر دوسرے لوگوں نے کی ہے پس انہوں نے ظلم اور جھوٹ کا ارتکاب کیا۔
۳۔ عملی سبق: قرآن پر الزام نہ لگاؤ؛ سچ اور جھوٹ کو پہچانو؛ ظلم و جھوٹ سے بچو۔"""
),
2860: (
"اور انہوں نے کہا یہ تو اگلے وقتوں کی کہانیاں ہیں جنہیں انہوں نے لکھوایا ہے — پس وہ اس پر صبح و شام پڑھائی جاتی ہیں",
"""۱۔ کافروں کا الزام — اگلے وقتوں کی کہانیاں؛ لکھوائی؛ صبح و شام۔
۲۔ ’’وَقَالُوا أَسَاطِيرُ الْأَوَّلِينَ اكْتَتَبَهَا فَهِيَ تُمْلَىٰ عَلَيْهِ بُكْرَۃً وَأَصِيلًا‘‘ — اور انہوں نے کہا یہ تو اگلے وقتوں کی کہانیاں ہیں جنہیں انہوں نے لکھوایا ہے — پس وہ اس پر صبح و شام پڑھائی جاتی ہیں — یعنی اور انہوں نے کہا یہ تو اگلے وقتوں کی کہانیاں ہیں جنہیں انہوں نے لکھوایا ہے پس وہ اس پر صبح و شام پڑھائی جاتی ہیں۔
۳۔ عملی سبق: قرآن کو اگلوں کی کہانی نہ سمجھو؛ اسے اللہ کا کلام مانو۔"""
),
2861: (
"کہہ دیجیے اسے اسی نے نازل کیا ہے جو آسمانوں اور زمین کے چھپے راز جانتا ہے — بے شک وہ غفور رحیم ہے",
"""۱۔ اللہ — السِّر کا علم؛ قرآن نازل کرنا؛ غفور رحیم۔
۲۔ ’’قُلْ أَنزَلَهُ الَّذِي يَعْلَمُ السِّرَّ فِي السَّمَاوَاتِ وَالْأَرْضِ إِنَّهُ كَانَ غَفُورًا رَّحِيمًا‘‘ — کہہ دیجیے اسے اسی نے نازل کیا ہے جو آسمانوں اور زمین کے چھپے راز جانتا ہے — بے شک وہ غفور رحیم ہے — یعنی کہہ دیجیے اسے اسی نے نازل کیا ہے جو آسمانوں اور زمین کے چھپے راز جانتا ہے بے شک وہ غفور رحیم ہے۔
۳۔ عملی سبق: قرآن کو اللہ کا کلام سمجھو؛ اس کی غفوریت و رحمت پر بھروسہ کرو۔"""
),
2862: (
"اور انہوں نے کہا اس رسولؐ کو کیا ہوا ہے کہ وہ کھانا کھاتا ہے اور بازاروں میں چلتا ہے — اس پر کوئی فرشتہ کیوں نہیں اتارا جاتا کہ وہ اس کے ساتھ نذیر ہوتا",
"""۱۔ کافروں کا الزام — کھانا؛ بازار؛ فرشتہ؛ نذیر۔
۲۔ ’’وَقَالُوا مَالِ هَٰذَا الرَّسُولِ يَأْكُلُ الطَّعَامَ وَيَمْشِي فِي الْأَسْوَاقِ لَوْلَا أُنزِلَ إِلَيْهِ مَلَكٌ فَيَكُونَ مَعَهُ نَذِيرًا‘‘ — اور انہوں نے کہا اس رسولؐ کو کیا ہوا ہے کہ وہ کھانا کھاتا ہے اور بازاروں میں چلتا ہے — اس پر کوئی فرشتہ کیوں نہیں اتارا جاتا کہ وہ اس کے ساتھ نذیر ہوتا — یعنی اور انہوں نے کہا اس رسولؐ کو کیا ہوا ہے کہ وہ کھانا کھاتا ہے اور بازاروں میں چلتا ہے اس پر کوئی فرشتہ کیوں نہیں اتارا جاتا کہ وہ اس کے ساتھ نذیر ہوتا۔
۳۔ عملی سبق: رسولؐ کو انسان ہونے کے لیے پیش کرو؛ ان کی نبوت پر ایمان رکھو۔"""
),
2863: (
"یا اس پر خزانے انڈیل دیے جاتے یا اس کا کوئی باغ ہوتا جس سے وہ کھاتا — اور ظالموں نے کہا تم تو بس ایک جادو کیے ہوئے شخص کی پیروی کر رہے ہو",
"""۱۔ کافروں کا الزام — خزانہ؛ باغ؛ جادو؛ ظالموں کا قول۔
۲۔ ’’أَوْ يُلْقَىٰ إِلَيْهِ كَنزٌ أَوْ تَكُونُ لَهُ جَنَّۃٌ يَأْكُلُ مِنْهَا وَقَالَ الظَّالِمُونَ إِن تَتَّبِعُونَ إِلَّا رَجُلًا مَّسْحُورًا‘‘ — یا اس پر خزانے انڈیل دیے جاتے یا اس کا کوئی باغ ہوتا جس سے وہ کھاتا — اور ظالموں نے کہا تم تو بس ایک جادو کیے ہوئے شخص کی پیروی کر رہے ہو — یعنی یا اس پر خزانے انڈیل دیے جاتے یا اس کا کوئی باغ ہوتا جس سے وہ کھاتا اور ظالموں نے کہا تم تو بس ایک جادو کیے ہوئے شخص کی پیروی کر رہے ہو۔
۳۔ عملی سبق: رسولؐ کو جادو زدہ نہ سمجھو؛ ان کی نبوت پر ایمان رکھو۔"""
),
2864: (
"دیکھیے انہوں نے آپ کے بارے میں کیسی مثالیں گھڑیں — پس وہ گمراہ ہو گئے — اب وہ کوئی راستہ نہیں پا سکتے",
"""۱۔ کافروں کی مثالیں — گمراہی؛ راستہ نہ پانا۔
۲۔ ’’انظُرْ كَيْفَ ضَرَبُوا لَكَ الْأَمْثَالَ فَضَلُّوا فَلَا يَسْتَطِيعُونَ سَبِيلًا‘‘ — دیکھیے انہوں نے آپ کے بارے میں کیسی مثالیں گھڑیں — پس وہ گمراہ ہو گئے — اب وہ کوئی راستہ نہیں پا سکتے — یعنی دیکھیے انہوں نے آپ کے بارے میں کیسی مثالیں گھڑیں پس وہ گمراہ ہو گئے اب وہ کوئی راستہ نہیں پا سکتے۔
۳۔ عملی سبق: رسولؐ کے خلاف مثالیں نہ گھڑو؛ ہدایت کی تلاش کرو۔"""
),
2865: (
"بابرکت ہے وہ جو اگر چاہے آپ کے لیے اس سے بہتر چیزیں بنا دے باغات جن کے نیچے سے نہریں بہتی ہیں اور آپ کے لیے محل بنا دے",
"""۱۔ اللہ — چاہنے پر بہتر چیزیں؛ باغات؛ نہریں؛ محل؛ اللہ کی قدرت۔
۲۔ ’’تَبَارَكَ الَّذِي إِن شَاءَ جَعَلَ لَكَ خَيْرًا مِّن ذَٰلِكَ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ وَيَجْعَل لَّكَ قُصُورًا‘‘ —بابرکت ہے وہ جو اگر چاہے آپ کے لیے اس سے بہتر چیزیں بنا دے باغات جن کے نیچے سے نہریں بہتی ہیں اور آپ کے لیے محل بنا دے۔
۳۔ عملی سبق: اللہ کی قدرت پر ایمان رکھو؛ اس کے انعامات کی امید رکھو؛ صبر کرو۔"""
),
}
